fn layout(app: &Studio, t: &Theme) -> View<StudioAction> {
    let tabs = tabview(["Design", "Build", "Ship"], app.tab)
        .style(full(180))
        .children(
            [
                "Shape the interface.",
                "Connect your application.",
                "Make it your own.",
            ]
            .iter()
            .map(|s| {
                studio_column()
                    .padding(20)
                    .child(styled_label(s, t.text, Font::montserrat_20()))
            }),
        )
        .on_value_changed(StudioAction::Tab);
    let tiles = tileview(
        [
            Tile::new(0, 0, ScrollDirection::RIGHT),
            Tile::new(1, 0, ScrollDirection::LEFT),
        ],
        app.tile,
    )
    .style(full(138))
    .children([
        studio_column()
            .background(TEAL)
            .padding(20)
            .child(styled_label("01 / Explore", WHITE, Font::montserrat_20())),
        studio_column()
            .background(BLUE)
            .padding(20)
            .child(styled_label("02 / Create", WHITE, Font::montserrat_20())),
    ])
    .on_value_changed(StudioAction::Tile);
    let grid = grid(
        [GridTrack::Fr(1), GridTrack::Fr(1)],
        [GridTrack::Fr(1), GridTrack::Fr(1)],
        (0..4).map(|i| {
            action_button(&format!("Cell {}", i + 1), StudioAction::Click, t)
                .key(Key::Id(400 + i))
                .grid_cell((i % 2) as u16, (i / 2) as u16, 1, 1)
                .grid_align(GridAlign::Stretch, GridAlign::Stretch)
                .background(if i == 0 { ORANGE } else { t.background })
        }),
    )
    .style(full(142).gap(12))
    .grid_navigation(GridNavigation::default());
    studio_column()
        .child(
            studio_row().children([
                half(
                    card(
                        "One space, three tabs",
                        "Native tabview / controlled selection",
                        t,
                    ),
                    308,
                )
                .child(tabs),
                half(
                    card(
                        "Swipe to the next idea",
                        "Native tileview / touch or button",
                        t,
                    ),
                    308,
                )
                .child(tiles)
                .child(action_button(
                    "Next tile",
                    StudioAction::Tile((1 - app.tile) as i32),
                    t,
                )),
            ]),
        )
        .child(
            studio_row().children([
                half(
                    card("A flexible grid", "Arrow-key navigation / equal tracks", t),
                    254,
                )
                .child(grid),
                half(
                    card(
                        "Flex, with intention",
                        "Rows / columns / nested surfaces",
                        t,
                    ),
                    254,
                )
                .child(
                    studio_row().children([
                        studio_column()
                            .width(percent(30))
                            .height(px(140))
                            .background(TEAL)
                            .radius(10)
                            .padding(16)
                            .child(styled_label("Side", WHITE, t.body_font)),
                        studio_column().grow(1).gap(12).children(
                            ["Header", "Content", "Footer"].iter().map(|name| {
                                container()
                                    .style(full(38).background(t.background).radius(8))
                                    .child(text(name, t).align(Align::Center))
                            }),
                        ),
                    ]),
                ),
            ]),
        )
}

const fn tile_pixels(alternate: bool) -> [u8; 72 * 72 * 2] {
    let mut pixels = [0u8; 72 * 72 * 2];
    let mut y = 0;
    while y < 72 {
        let mut x = 0;
        while x < 72 {
            let dx = x as i32 - 36;
            let dy = y as i32 - 36;
            let (r, g, b) = if dx * dx + dy * dy < 25 * 25 {
                if alternate {
                    (91u16, 117u16, 218u16)
                } else {
                    (225, 88, 47)
                }
            } else if x % 12 < 1 || y % 12 < 1 {
                (208, 222, 211)
            } else {
                (234, 241, 231)
            };
            let value = ((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3);
            let index = (y * 72 + x) * 2;
            pixels[index] = value as u8;
            pixels[index + 1] = (value >> 8) as u8;
            x += 1;
        }
        y += 1;
    }
    pixels
}
static TILE_A: [u8; 72 * 72 * 2] = tile_pixels(false);
static TILE_B: [u8; 72 * 72 * 2] = tile_pixels(true);

fn canvas_page(app: &Studio, t: &Theme) -> View<StudioAction> {
    let mut frame = Canvas::new(940, 205).background(INK, 255);
    for x in (20..940).step_by(40) {
        frame = frame.draw(DrawCommand::Line {
            from: (x, 20),
            to: (x, 185),
            width: 1,
            color: Color::rgb(43, 53, 67),
            opacity: 255,
        });
    }
    for y in (25..205).step_by(40) {
        frame = frame.draw(DrawCommand::Line {
            from: (20, y),
            to: (920, y),
            width: 1,
            color: Color::rgb(43, 53, 67),
            opacity: 255,
        });
    }
    for x in 1..890_i16 {
        let y = |v: i16| (110.0 + (f32::from(v) / 68.0).sin() * 43.0) as i16;
        frame = frame.draw(DrawCommand::Line {
            from: (x + 20, y(x - 1)),
            to: (x + 21, y(x)),
            width: 3,
            color: ORANGE,
            opacity: 255,
        });
    }
    frame = frame
        .draw(DrawCommand::Rect {
            x: 38,
            y: 28,
            width: 138,
            height: 34,
            radius: 8,
            color: TEAL,
            opacity: 255,
        })
        .draw(DrawCommand::Text {
            x: 50,
            y: 36,
            width: 120,
            height: 24,
            text: "CANVAS / LIVE".into(),
            font: t.body_font,
            color: WHITE,
            opacity: 255,
        })
        .draw(DrawCommand::Pixel {
            x: 20,
            y: 20,
            color: WHITE,
            opacity: 255,
        });
    studio_column()
        .child(
            card(
                "Your pixels, your rules",
                "Lines / rounded rectangles / text / pixels",
                t,
            )
            .style(full(315))
            .child(rs_lvgl_ui::canvas(frame)),
        )
        .child(
            studio_row().children([
                third(card("Curved type", "Arc label", t), 248).child(
                    arc_label("RUST / LVGL", 48, 200, 160)
                        .width(px(200))
                        .height(px(130))
                        .text_color(TEAL)
                        .font(Font::montserrat_16()),
                ),
                third(
                    card("Native motion", "Scoped animation / reversible", t),
                    248,
                )
                .child(
                    container().style(full(110)).scrollable(false).child(
                        container()
                            .width(px(42))
                            .height(px(42))
                            .background(ORANGE)
                            .radius(12)
                            .align(Align::CenterLeft)
                            .animate(
                                Animation::new(AnimationProperty::X, 12, 200, 1400)
                                    .reverse(1400)
                                    .repeat(u32::MAX)
                                    .easing(Easing::EaseInOut),
                            ),
                    ),
                ),
                third(
                    card("Custom properties", "Props / tick / cleanup", t),
                    248,
                )
                .gap(8)
                .child(custom(super::native::Gauge::default(), super::native::GaugeProps {
                    value: app.value, color: TEAL, track: t.background,
                }).key(Key::Named("custom-gauge")))
                .child(row([
                    action_button("-5", StudioAction::Step(-5), t),
                    text(&format!("{}%", app.value), t),
                    action_button("+5", StudioAction::Step(5), t),
                ]).gap(10).align_items(ItemAlign::Center)),
            ]),
        )
}

fn composition(app: &Studio, t: &Theme) -> View<StudioAction> {
    let list = list::list(
        t,
        [
            ListItem::new("Studio workspace")
                .detail("Your components in one place")
                .on_click(StudioAction::Click)
                .view(t),
            ListItem::new("Device settings")
                .detail("Open the next page")
                .chevron(true)
                .on_click(StudioAction::Push)
                .view(t),
        ],
    )
    .style(full(136));
    let files = file_explorer::view(
        t,
        "/studio/assets",
        Some(StudioAction::File(0)),
        [
            FileEntry::directory(1, "Animations", StudioAction::File(1)),
            FileEntry::file(2, "studio-motion.json", StudioAction::File(2)),
            FileEntry::file(3, "status.gif", StudioAction::File(3)),
        ],
    )
    .style(full(160));
    studio_column()
        .child(
            studio_row().children([
                half(
                    Panel::new("Your workspace")
                        .action(action_button("Details", StudioAction::Push, t))
                        .child(list)
                        .view(t),
                    268,
                )
                .radius(16),
                half(
                    card(
                        "Files, without surprises",
                        "Application-provided sample entries",
                        t,
                    ),
                    278,
                )
                .child(files),
            ]),
        )
        .child(
            studio_row().children([
                half(
                    card("Go a little deeper", "Stack navigation / back behavior", t),
                    306,
                )
                .child(
                    nav::view(
                        &app.nav,
                        t,
                        *app.nav.current(),
                        studio_column()
                            .child(
                                text(
                                    if app.nav.can_go_back() {
                                        "A nested page. Back returns to the workspace."
                                    } else {
                                        "Start with a page, then push another."
                                    },
                                    t,
                                )
                                .width(percent(100)),
                            )
                            .child(action_button(
                                if app.nav.can_go_back() {
                                    "Back to workspace"
                                } else {
                                    "Open device"
                                },
                                if app.nav.can_go_back() {
                                    StudioAction::Back
                                } else {
                                    StudioAction::Push
                                },
                                t,
                            )),
                        StudioAction::Back,
                    )
                    .style(full(164)),
                ),
                half(
                    card("A moment of attention", "Message box / modal / toast", t).gap(10),
                    306,
                )
                .child(
                    message_box("Everything is ready.")
                        .message_box_title("Workspace prepared")
                        .message_box_buttons(["Got it"])
                        .style(full(140))
                        .on_value_changed(|_| StudioAction::Toast),
                )
                .child(studio_row().padding(6).children([
                    primary("Open dialog", StudioAction::Dialog(true), t),
                    action_button("Show toast", StudioAction::Toast, t),
                ])),
            ]),
        )
}

//! Native-only samples, bounded by the mounted custom node's lifetime.
use super::*;
use rs_lvgl::NativeObject;

pub(super) fn view(app: &Studio, t: &Theme) -> View<StudioAction> {
    let mut samples = Vec::new();
    for (kind, title, caption) in [
        (0, "Native list", "Select a sample action"),
        (1, "Native menu", "Open Display, then use Back"),
        (2, "Native window", "Header / content / action"),
    ] {
        // SAFETY: each factory returns a direct child of the supplied parent.
        // All descendants and native menu callbacks are owned by that subtree;
        // strings are static or copied by LVGL. No pointers escape the factory.
        let sample = unsafe { raw(move |parent| {
            let obj = match kind {
                0 => rs_lvgl_sys::lv_list_create(parent.as_ptr()),
                1 => rs_lvgl_sys::lv_menu_create(parent.as_ptr()),
                _ => rs_lvgl_sys::lv_win_create(parent.as_ptr()),
            };
            let object = NonNull::new(obj)?;
            rs_lvgl_sys::lv_obj_set_size(obj, rs_lvgl_sys::lv_pct(100), 306);
            match kind {
                0 => {
                    rs_lvgl_sys::lv_list_add_text(obj, c"STUDIO COLLECTION".as_ptr().cast());
                    for name in [c"New workspace", c"Open a sample", c"Save a preset", c"Export a snapshot"] {
                        rs_lvgl_sys::lv_list_add_button(obj, core::ptr::null(), name.as_ptr().cast());
                    }
                }
                1 => {
                    let page = rs_lvgl_sys::lv_menu_page_create(obj, c"Device".as_ptr().cast());
                    let details = rs_lvgl_sys::lv_menu_page_create(obj, c"Display".as_ptr().cast());
                    let settings = rs_lvgl_sys::lv_menu_cont_create(page);
                    let label = rs_lvgl_sys::lv_label_create(settings);
                    rs_lvgl_sys::lv_label_set_text(label, c"Display  >".as_ptr().cast());
                    let label = rs_lvgl_sys::lv_label_create(details);
                    rs_lvgl_sys::lv_label_set_text(label, c"1280 x 860\nRGB color\nNative rendering".as_ptr().cast());
                    rs_lvgl_sys::lv_menu_set_load_page_event(obj, settings, details);
                    rs_lvgl_sys::lv_menu_set_page(obj, page);
                }
                _ => {
                    rs_lvgl_sys::lv_win_add_title(obj, c"Sample device".as_ptr().cast());
                    rs_lvgl_sys::lv_win_add_button(obj, c"\u{f067}".as_ptr().cast(), 42);
                    let label = rs_lvgl_sys::lv_label_create(rs_lvgl_sys::lv_win_get_content(obj));
                    rs_lvgl_sys::lv_label_set_text(label, c"A native window.\n\nComposed inside a Rust view.\n\nPress the header action.".as_ptr().cast());
                }
            }
            enable_bubbling(obj);
            Some(object)
        }) }.key(Key::Id(700 + kind + if app.dark { 10 } else { 0 }))
    ;
        samples.push(
            card(title, caption, t)
                .width(percent(32))
                .height(px(430))
                .child(sample)
                .on_bubbled_event(|event| {
                    matches!(
                        event,
                        InputEvent::Other(Event::Clicked)
                            | InputEvent::Pointer(PointerEvent {
                                event: Event::Clicked,
                                ..
                            })
                    )
                    .then_some(StudioAction::Click)
                }),
        );
    }
    studio_column().child(studio_row().children(samples))
        .child(card("One native provider. Three ways to build.", "Typed views / imperative widgets / raw C bindings",t).height(px(128))
            .child(text(&format!("{} native actions received. Native samples keep their children and callbacks inside one mounted subtree.",app.clicks),t)
                .width(percent(100))))
}

#[derive(Default)]
pub(super) struct Gauge {
    elapsed: u32,
}
pub(super) struct GaugeProps {
    pub value: i32,
    pub color: Color,
    pub track: Color,
}
impl CustomWidget for Gauge {
    type Props = GaugeProps;
    fn validate(props: &GaugeProps) -> Result<(), UiError> {
        if (0..=100).contains(&props.value) {
            Ok(())
        } else {
            Err(UiError::InvalidProperty)
        }
    }
    fn create(&mut self, parent: &mut Obj<'_>, _: &GaugeProps) -> Result<CustomObject, UiError> {
        // SAFETY: the new direct child is returned to the mounted owner. No
        // native pointer or application state escapes a hook.
        unsafe {
            let root = NonNull::new(rs_lvgl_sys::lv_arc_create(parent.raw().as_ptr()))
                .ok_or(UiError::Allocation)?;
            rs_lvgl_sys::lv_obj_set_size(root.as_ptr(), 72, 72);
            rs_lvgl_sys::lv_arc_set_range(root.as_ptr(), 0, 100);
            rs_lvgl_sys::lv_arc_set_bg_angles(root.as_ptr(), 135 as _, 405 as _);
            rs_lvgl_sys::lv_obj_set_style_arc_width(
                root.as_ptr(),
                8,
                rs_lvgl_sys::lv_part_t_LV_PART_MAIN,
            );
            rs_lvgl_sys::lv_obj_set_style_arc_width(
                root.as_ptr(),
                8,
                rs_lvgl_sys::lv_part_t_LV_PART_INDICATOR,
            );
            rs_lvgl_sys::lv_obj_set_style_opa(
                root.as_ptr(),
                0,
                rs_lvgl_sys::lv_part_t_LV_PART_KNOB,
            );
            rs_lvgl_sys::lv_obj_set_clickable(root.as_ptr(), false);
            CustomObject::new(parent, root)
        }
    }
    fn apply_props(
        &mut self,
        object: &mut CustomObject,
        props: &GaugeProps,
    ) -> Result<(), UiError> {
        let color = |c: Color| rs_lvgl_sys::lv_color_t {
            red: c.r,
            green: c.g,
            blue: c.b,
        };
        // SAFETY: a live borrowed arc; LVGL copies every numeric/color value.
        unsafe {
            rs_lvgl_sys::lv_arc_set_value(object.raw().as_ptr(), props.value);
            rs_lvgl_sys::lv_obj_set_style_arc_color(
                object.raw().as_ptr(),
                color(props.color),
                rs_lvgl_sys::lv_part_t_LV_PART_INDICATOR,
            );
            rs_lvgl_sys::lv_obj_set_style_arc_color(
                object.raw().as_ptr(),
                color(props.track),
                rs_lvgl_sys::lv_part_t_LV_PART_MAIN,
            );
        }
        Ok(())
    }
    fn tick(&mut self, object: &mut CustomObject, elapsed_ms: u32) -> Result<(), UiError> {
        self.elapsed = self.elapsed.wrapping_add(elapsed_ms);
        let phase = (self.elapsed % 1600) as f32 / 1600.0 * std::f32::consts::TAU;
        let opacity = (220.0 + 35.0 * phase.sin()) as u8;
        // SAFETY: time changes only indicator opacity, independently of model value.
        unsafe {
            rs_lvgl_sys::lv_obj_set_style_arc_opa(
                object.raw().as_ptr(),
                opacity,
                rs_lvgl_sys::lv_part_t_LV_PART_INDICATOR,
            );
        }
        Ok(())
    }
    fn delete(&mut self, _: &mut CustomObject) {
        self.elapsed = 0;
    }
}

/// Enable event forwarding within a newly created subtree.
///
/// # Safety
/// The caller must supply a live subtree on the LVGL thread, with no concurrent
/// deletion. No pointer escapes; recursion touches only current descendants.
unsafe fn enable_bubbling(root: *mut rs_lvgl_sys::lv_obj_t) {
    unsafe {
        rs_lvgl_sys::lv_obj_set_event_bubble(root, true);
        for i in 0..rs_lvgl_sys::lv_obj_get_child_count(root) {
            enable_bubbling(rs_lvgl_sys::lv_obj_get_child(root, i as i32));
        }
    }
}

//! Interactive presentation, axes, point cursors and bounded canonical history.
use super::*;
use core::num::NonZeroU32;

pub(super) fn history() -> ChartHistory {
    let mut history = ChartHistory::new(1, NonZeroU32::new(12).unwrap(), ChartSampleKind::Y);
    for value in [20, 33, 27, 56, 43, 70, 62, 79, 68, 84, 74, 92] {
        history.push_y(value).unwrap();
    }
    history
}
fn cursor(index: u32) -> ChartCursor {
    ChartCursor::new(
        1,
        BLUE,
        ChartCursorDirection::Both,
        ChartCursorTarget::Point { series: 1, index },
    )
}
fn plot(spec: ChartSpec, key: &'static str, height: i16) -> View<StudioAction> {
    chart(spec)
        .key(Key::Named(key))
        .width(percent(100))
        .height(px(height))
        .padding(10)
        .border(Color::rgb(0, 0, 0), 0)
        .background_opacity(0)
        .on_click(StudioAction::ChartNext)
}
pub(super) fn view(app: &Studio, theme: &Theme) -> View<StudioAction> {
    let kind = [
        ChartType::Line,
        ChartType::Bar,
        ChartType::Stacked,
        ChartType::Curve,
        ChartType::Scatter,
    ][app.chart_form];
    let data = if kind == ChartType::Scatter {
        ChartData::xy([(0, 20), (20, 70), (40, 35), (60, 85), (80, 55), (100, 90)])
    } else {
        ChartData::values([20, 70, 35, 85, 55, 90])
    };
    let mut description = ChartSpec::new(
        kind,
        ChartAxes::new(ChartRange::new(0, 100), ChartRange::new(0, 100)),
        vec![ChartSeries::new(1, ORANGE, data)],
    );
    let secondary = if kind == ChartType::Scatter {
        ChartData::xy([
            (1000, 100),
            (1200, 400),
            (1400, 180),
            (1600, 600),
            (1800, 300),
            (2000, 700),
        ])
    } else {
        ChartData::values([10, 40, 18, 60, 30, 70])
    };
    description.axes.secondary_x = ChartRange::new(1000, 2000);
    description.axes.secondary_y = ChartRange::new(0, 1000);
    description
        .series
        .push(ChartSeries::new(2, TEAL, secondary).axes(
            ChartAxis::Secondary,
            if kind == ChartType::Stacked {
                ChartAxis::Primary
            } else {
                ChartAxis::Secondary
            },
        ));
    description.cursors.push(cursor(app.chart_point % 6));
    let presentation = card(
        "Choose a presentation",
        "Click the plot to move its point cursor.",
        theme,
    )
    .height(px(260))
    .child(
        row([
            text(&format!("{kind:?} / point {}", app.chart_point % 6), theme),
            action_button("Next form", StudioAction::ChartForm, theme),
        ])
        .gap(16)
        .align_items(ItemAlign::Center),
    )
    .child(plot(description, "advanced-chart", 100));
    let mut description = ChartSpec::new(
        ChartType::Line,
        ChartAxes::new(ChartRange::new(0, 100), ChartRange::new(0, 100)),
        vec![ChartSeries::new(
            1,
            TEAL,
            ChartData::History(app.chart_history.snapshot()),
        )],
    );
    description.update_mode = if app.chart_circular {
        ChartUpdateMode::Circular
    } else {
        ChartUpdateMode::Shift
    };
    description.cursors.push(cursor(app.chart_point % 12));
    let history = card(
        "A bounded signal",
        "Add samples, skip a batch or start a new epoch.",
        theme,
    )
    .height(px(300))
    .child(
        row([
            action_button("Add sample", StudioAction::ChartAppend(1), theme),
            action_button("Burst 16", StudioAction::ChartAppend(16), theme),
            action_button("Clear history", StudioAction::ChartClear, theme),
            text("Circular", theme),
            switch(app.chart_circular).on_toggle(StudioAction::ChartCircular),
        ])
        .gap(10)
        .align_items(ItemAlign::Center),
    )
    .child(text(
        &format!(
            "epoch {} / {} retained / next {}",
            app.chart_history.epoch(),
            app.chart_history.len(),
            app.chart_history.next_sequence()
        ),
        theme,
    ))
    .child(plot(description, "history-chart", 110));
    studio_column().child(presentation).child(history)
}
